    },
    {
      "start": 163,
      "subgoal": "Distinguish native and web deployment for VR applications and identify the corresponding platforms."
    },
    {
      "start": 174,
      "subgoal": "Describe native VR SDKs and examples of SDKs for different head-mounted displays."
    },
    {
      "start": 194,
      "subgoal": "Describe the categories of web deployment tools and examples in each category."
    },
    {
      "start": 219,
      "subgoal": "Summarize the main points of the lecture and preview the next topic, AR software."
    }
  ]
}

